{
  "framing_conflicto_politico_vs_tecnologico": {
    "definicion": "Consiste en presentar un tema bajo la óptica de un conflicto político en lugar de enfocarse en sus aspectos tecnológicos, resaltando tensiones ideológicas y polarizando la percepción del asunto.",
    "ejemplo": "En noviembre de 2024, varios medios estadounidenses cubrieron el debate sobre la regulación de la IA enfatizando la disputa entre partidos sobre la soberanía digital, mientras minimizaban los avances técnicos y sus implicaciones éticas.",
    "como_detectarla": "1. Identifica si la cobertura prioriza la posición de partidos o líderes políticos. 2. Verifica la escasez de explicaciones técnicas sobre el tema. 3. Busca titulares que enmarquen la cuestión como una lucha de poder en vez de una discusión tecnológica."
  },
  "omision_tema_relevante": {
    "definicion": "Técnica comunicativa que consiste en excluir deliberadamente información o asuntos de gran importancia para la audiencia, orientando la narrativa hacia otros contenidos menos críticos.",
    "ejemplo": "Durante la cobertura de la cumbre climática de 2023, algunos periódicos internacionales omitieron mencionar la ausencia de compromisos vinculantes de los países más emisores, enfocándose solo en declaraciones de líderes menores.",
    "como_detectarla": "1. Contrasta la noticia con otras fuentes que traten el mismo evento. 2. Detecta lagunas de información clave que suelen estar presentes en análisis completos. 3. Pregunta qué datos faltan para comprender plenamente la situación."
  },
  "framing_noticias_locales_culturales": {
    "definicion": "Enmarca hechos locales o culturales como representativos de tendencias más amplias, otorgándoles un peso simbólico que trasciende su alcance geográfico o sectorial.",
    "ejemplo": "En junio de 2024, la protesta de artistas en Barcelona contra la gentrificación fue presentada por varios medios como el síntoma de una crisis cultural europea, a pesar de ser un conflicto urbano concreto.",
    "como_detectarla": "1. Analiza si se extrapolan conclusiones generales a partir de un caso puntual. 2. Revisa si se citan comparaciones con fenómenos fuera del contexto local. 3. Evalúa la presencia de datos que justifiquen la ampliación del alcance."
  },
  "enfoque_selectivo_controversias_politicas": {
    "definicion": "Selecciona y destaca exclusivamente los aspectos más polémicos de un debate político, omitiendo matices, consensos o datos equilibrados, con el fin de intensificar la percepción de conflicto.",
    "ejemplo": "En la cobertura de la reforma electoral de EE.UU. en 2024, algunos canales de televisión resaltaron solo los argumentos de los críticos más radicales, dejando fuera las propuestas moderadas de ambas partes.",
    "como_detectarla": "1. Identifica si la pieza informativa se concentra solo en declaraciones extremas. 2. Busca ausencia de posiciones centristas o datos estadísticos neutrales. 3. Comprueba si se omiten contextos que suavizan la controversia."
  },
  "framing_amenaza_social_citas_polemicas": {
    "definicion": "Utiliza citas controvertidas de figuras públicas para presentar un fenómeno como una amenaza directa a la cohesión social, generando alarma y polarización en la audiencia.",
    "ejemplo": "En octubre de 2024, un noticiero citó fuera de contexto a un influyente creador de contenido digital, insinuando que sus opiniones fomentaban la violencia contra minorías, lo que provocó una ola de temor social.",
    "como_detectarla": "1. Verifica la veracidad y el contexto original de la cita. 2. Observa si la narrativa enfatiza la peligrosidad basada solo en esa declaración. 3. Analiza si se incluyen contraargumentos o perspectivas que mitiguen la percepción de amenaza."
  }
}
